CREATE OR REPLACE EDITIONABLE FUNCTION "%USER_NAME%"."DOCUMENTATION_LATE" (P_SID NUMBER) RETURN BOOLEAN
AS
    vBool BOOLEAN DEFAULT FALSE;
BEGIN
    FOR c IN (
        SELECT
            TO_NUMBER(NVL(date_submitted, et_sysdate) - (time_end + (date_session - TRUNC(time_end, 'DD')))) * 24 hrs
        FROM sessions
        WHERE s_id = p_sid
        )
    LOOP
        IF c.hrs > 48 THEN
            vBool := TRUE;
        END IF;
    END LOOP;

    RETURN vBool;
END DOCUMENTATION_LATE;
/
